package realtimelive

import (
	"bytes"
	"context"
	"encoding/json"
	"errors"
	"io"
	"net"
	"net/http"
	"os"
	"path/filepath"
	"regexp"
	"syscall"
	"time"
)

var ErrMemoryBusy = errors.New("memory_busy")
var ErrMemoryClearForbidden = errors.New("memory_clear_forbidden")
var errMemoryClearUnconfirmed = errors.New("memory_clear_unconfirmed")
var memoryControlDevice = regexp.MustCompile(`^dev_[a-f0-9]{32}$`)
var memoryControlIdent = regexp.MustCompile(`^[A-Za-z0-9_-]{1,64}$`)

// Claims are generated by management, never accepted from its public client.
// The guard rechecks current authority under the configuration writer lock.
type MemoryClearClaim struct {
	DeviceID       string    `json:"deviceId"`
	ActorID        string    `json:"actorId"`
	FamilyID       string    `json:"familyId"`
	BindingID      string    `json:"bindingId"`
	BindingVersion int       `json:"bindingVersion"`
	Deadline       time.Time `json:"deadline"`
}
type MemoryClearGuard func(context.Context, MemoryClearClaim, func() error) error

func (c MemoryClearClaim) valid() bool {
	return memoryControlDevice.MatchString(c.DeviceID) && memoryControlIdent.MatchString(c.ActorID) && memoryControlIdent.MatchString(c.FamilyID) && memoryControlIdent.MatchString(c.BindingID) && c.BindingVersion > 0 && !c.Deadline.IsZero() && time.Now().Before(c.Deadline)
}

func (s *Server) ClearDeviceMemory(ctx context.Context, claim MemoryClearClaim, guard MemoryClearGuard) error {
	if !claim.valid() || guard == nil {
		return ErrMemoryClearForbidden
	}
	if err := ctx.Err(); err != nil {
		return err
	}
	s.mu.Lock()
	if s.stopping || s.memory == nil || s.memoryErr != nil {
		s.mu.Unlock()
		return errMemoryClearUnconfirmed
	}
	if s.leases[claim.DeviceID] != nil || s.clearing[claim.DeviceID] {
		s.mu.Unlock()
		return ErrMemoryBusy
	}
	if s.clearing == nil {
		s.clearing = map[string]bool{}
	}
	s.clearing[claim.DeviceID] = true
	s.clearWG.Add(1)
	s.mu.Unlock()
	defer func() { s.mu.Lock(); delete(s.clearing, claim.DeviceID); s.mu.Unlock(); s.clearWG.Done() }()
	return guard(ctx, claim, func() error {
		if err := ctx.Err(); err != nil {
			return err
		}
		if !claim.valid() {
			return ErrMemoryClearForbidden
		}
		return clearStoredMemory(ctx, s.memory, claim.DeviceID)
	})
}

// This handler belongs only on the private Unix listener, never Handler().
func (s *Server) MemoryControlHandler(guard MemoryClearGuard) http.Handler {
	mux := http.NewServeMux()
	mux.HandleFunc("POST /memory/clear", func(w http.ResponseWriter, r *http.Request) {
		var claim MemoryClearClaim
		raw, e := io.ReadAll(http.MaxBytesReader(w, r.Body, 4096))
		if e != nil || !strictMemoryClaim(raw, &claim) || !claim.valid() {
			respond(w, 400, map[string]string{"code": "invalid_request"})
			return
		}
		ctx, cancel := context.WithDeadline(r.Context(), claim.Deadline)
		defer cancel()
		e = s.ClearDeviceMemory(ctx, claim, guard)
		switch {
		case e == nil:
			respond(w, 200, map[string]string{"deviceId": claim.DeviceID, "status": "confirmed"})
		case errors.Is(e, ErrMemoryBusy):
			respond(w, 409, map[string]string{"code": "memory_busy"})
		case errors.Is(e, ErrMemoryClearForbidden):
			respond(w, 403, map[string]string{"code": "forbidden"})
		default:
			respond(w, 503, map[string]string{"code": "memory_clear_unconfirmed"})
		}
	})
	return mux
}
func strictMemoryClaim(raw []byte, c *MemoryClearClaim) bool {
	d := json.NewDecoder(bytes.NewReader(raw))
	tok, e := d.Token()
	if e != nil || tok != json.Delim('{') {
		return false
	}
	seen := map[string]bool{}
	allowed := map[string]bool{"deviceId": true, "actorId": true, "familyId": true, "bindingId": true, "bindingVersion": true, "deadline": true}
	for d.More() {
		tok, e = d.Token()
		k, ok := tok.(string)
		if e != nil || !ok || seen[k] || !allowed[k] {
			return false
		}
		seen[k] = true
		var v json.RawMessage
		if d.Decode(&v) != nil {
			return false
		}
	}
	if _, e = d.Token(); e != nil || len(seen) != len(allowed) {
		return false
	}
	var extra any
	if d.Decode(&extra) != io.EOF {
		return false
	}
	return json.Unmarshal(raw, c) == nil
}

// Only a dedicated root-owned private parent is accepted. Ancestors cannot be
// symlinks; an existing socket must itself be private and root-owned.
func ValidateMemoryControlSocket(path string) error {
	if !filepath.IsAbs(path) || filepath.Clean(path) != path || len(path) > 100 {
		return errMemoryClearUnconfirmed
	}
	parent := filepath.Dir(path)
	for p := parent; ; p = filepath.Dir(p) {
		st, e := os.Lstat(p)
		if e != nil || !st.IsDir() || st.Mode()&os.ModeSymlink != 0 {
			return errMemoryClearUnconfirmed
		}
		if p == parent {
			sys, ok := st.Sys().(*syscall.Stat_t)
			if !ok || sys.Uid != 0 || st.Mode().Perm() != 0700 {
				return errMemoryClearUnconfirmed
			}
		}
		if p == "/" {
			break
		}
	}
	st, e := os.Lstat(path)
	if os.IsNotExist(e) {
		return nil
	}
	if e != nil {
		return errMemoryClearUnconfirmed
	}
	sys, ok := st.Sys().(*syscall.Stat_t)
	if !ok || sys.Uid != 0 || st.Mode()&os.ModeSocket == 0 || st.Mode().Perm() != 0600 {
		return errMemoryClearUnconfirmed
	}
	return nil
}
func ListenMemoryControl(path string) (net.Listener, error) {
	if e := ValidateMemoryControlSocket(path); e != nil {
		return nil, e
	}
	if before, e := os.Lstat(path); e == nil {
		conn, e := net.DialTimeout("unix", path, 200*time.Millisecond)
		if e == nil {
			conn.Close()
			return nil, errMemoryClearUnconfirmed
		}
		if !errors.Is(e, syscall.ECONNREFUSED) {
			return nil, errMemoryClearUnconfirmed
		}
		current, e := os.Lstat(path)
		if e != nil || !os.SameFile(before, current) {
			return nil, errMemoryClearUnconfirmed
		}
		if e = os.Remove(path); e != nil {
			return nil, e
		}
	}
	ln, e := net.ListenUnix("unix", &net.UnixAddr{Name: path, Net: "unix"})
	if e != nil {
		return nil, e
	}
	if e = os.Chmod(path, 0600); e != nil {
		ln.Close()
		return nil, e
	}
	return ln, nil
}
